use vstd::prelude::*;

verus! {
    /// Given a 1D array `arr` of `f32`, produce a 2D array `result`
    /// with exactly one row, preserving the elements and their order.
    fn atleast_2d(arr: Vec<f32>) -> (result: Vec<Vec<f32>>)
        ensures
            // Exactly one row
            result.len() == 1,
            // That row has the same length as the input
            result[0].len() == arr.len(),
            // And for each index, the element is the same
            forall |i: usize| i < arr.len() ==> result[0][i] == arr[i],
    {
        // We start with an empty Vec<Vec<f32>>
        let mut result: Vec<Vec<f32>> = Vec::new();
        // Push the input array as the single row.
        // This moves `arr` into `result[0]`.
        result.push(arr);
        result
    }
}

fn main() {
    // example usage
    let a = vec![1.0f32, 2.5, 3.75];
    let m = atleast_2d(a.clone());
    assert!(m.len() == 1);
    assert!(m[0].len() == a.len());
    for i in 0..a.len() {
        assert!(m[0][i] == a[i]);
    }
}